import { useEffect, useMemo, useRef, useState, type ReactNode } from 'react';
import { QueryClient, QueryClientProvider, useQueryClient } from '@tanstack/react-query';
import { ClerkProvider, SignIn, SignUp, useClerk, useUser } from '@clerk/react';
import { publishableKeyFromHost } from '@clerk/react/internal';
import { shadcn } from '@clerk/themes';
import { ErrorBoundary } from '@/components/error-boundary';
import { Toaster } from '@/components/ui/toaster';
import { TooltipProvider } from '@/components/ui/tooltip';
import NotFound from '@/pages/not-found';
import { Route, Switch, useLocation, useParams, Router as WouterRouter, Link } from 'wouter';
import { useChatAboutProduct, useCreateGuestOrder, useCreateAdminProduct, useDeleteAdminProduct, useGetAdminOrders, useGetAdminProducts, useGetProduct, useGetProducts, useGetSimilarProducts, useUpdateAdminProduct, getGetProductsQueryKey, getGetAdminProductsQueryKey, getGetAdminOrdersQueryKey } from '@workspace/api-client-react';
import type { GuestOrderInput, Product, ProductInput } from '@workspace/api-client-react';
import { ArrowLeft, ArrowRight, ArrowUpRight, Check, ChevronLeft, ChevronRight, CircleHelp, Cpu, HardDrive, Laptop, Layers3, LogOut, Menu, Minus, PackageCheck, Plus, Search, ShieldCheck, ShoppingBag, SlidersHorizontal, Sparkles, Truck, X } from 'lucide-react';
