const queryClient = new QueryClient();
const basePath = import.meta.env.BASE_URL.replace(/\/$/, '');
const clerkPubKey = publishableKeyFromHost(window.location.hostname, import.meta.env.VITE_CLERK_PUBLISHABLE_KEY);
const clerkProxyUrl = import.meta.env.VITE_CLERK_PROXY_URL;
function stripBase(path: string): string {
  return basePath && path.startsWith(basePath) ? path.slice(basePath.length) || '/' : path;
}
if (!clerkPubKey) throw new Error('Missing VITE_CLERK_PUBLISHABLE_KEY in .env file');
type CartLine = { productId: string; quantity: number };
const CART_KEY = 'synkline-cart';
const readCart = (): CartLine[] => { try { return JSON.parse(localStorage.getItem(CART_KEY) || '[]') as CartLine[]; } catch { return []; } };
const money = (value: number) => new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 }).format(value);
const fallbackPhoto = 'https://images.pexels.com/photos/18105/pexels-photo.jpg?auto=compress&cs=tinysrgb&w=1000';

function Header({ cartCount = 0 }: { cartCount?: number }) {
  const [menuOpen, setMenuOpen] = useState(false);
  return <><div className="topline px-5 py-2 text-center">A GOOD MACHINE CHANGES YOUR EVERYDAY. FIND YOURS.</div><header className="nav-shell sticky top-0 z-40">
    <div className="mx-auto flex max-w-7xl items-center justify-between px-5 py-4 lg:px-8">
      <Link href="/" className="brand-mark flex items-center gap-2.5 text-[21px] text-[#173c69]" data-testid="link-home"><span className="flex h-8 w-8 items-center justify-center rounded-lg bg-[#2469c9] text-white"><Laptop size={18}/></span>synkline<span className="text-[#6a8caf]">.</span></Link>
      <nav className="hidden items-center gap-8 text-sm font-medium text-[#52677e] md:flex"><Link href="/" className="hover:text-[#2469c9]">Shop laptops</Link><a href="/#compare" className="hover:text-[#2469c9]">Compare</a><a href="/#guidance" className="hover:text-[#2469c9]">Buying guide</a></nav>
      <div className="flex items-center gap-3"><Link href="/checkout" className="relative flex items-center gap-2 rounded-full border border-[#d7e1eb] bg-white px-4 py-2 text-sm font-semibold text-[#264463] hover:border-[#2469c9]" data-testid="link-cart"><ShoppingBag size={17}/><span className="hidden sm:inline">Your bag</span>{cartCount > 0 && <span className="absolute -right-1 -top-1 flex h-5 min-w-5 items-center justify-center rounded-full bg-[#2469c9] px-1 text-[10px] text-white">{cartCount}</span>}</Link><button className="rounded-lg p-2 text-[#23415f] md:hidden" aria-label="Toggle navigation" onClick={() => setMenuOpen(!menuOpen)} data-testid="button-mobile-menu"><Menu size={20}/></button></div>
    </div>
    {menuOpen && <nav className="grid gap-3 border-t border-[#e1e8ef] px-5 py-4 text-sm md:hidden"><Link href="/" onClick={() => setMenuOpen(false)}>Shop laptops</Link><a href="/#compare" onClick={() => setMenuOpen(false)}>Compare models</a><a href="/#guidance" onClick={() => setMenuOpen(false)}>Buying guide</a></nav>}
  </header></>;
}

function Footer() { return <footer className="mt-20 border-t border-[#dce4ec] bg-[#edf2f7]"><div className="mx-auto grid max-w-7xl gap-8 px-5 py-10 md:grid-cols-[1fr_auto] lg:px-8"><div><Link href="/" className="brand-mark text-xl text-[#173c69]">synkline.</Link><p className="mt-2 max-w-sm text-sm leading-6 text-[#68798d]">Straightforward laptop shopping, with the details you need and room to choose at your own pace.</p></div><div className="flex flex-wrap items-center gap-x-7 gap-y-3 text-sm text-[#52677e]"><a href="/#compare">Compare</a><a href="/#guidance">Buying guide</a><Link href="/admin">Store access</Link></div><p className="text-xs text-[#8794a3] md:col-span-2">© 2025 Synkline Stores · Clear specs. Confident choices.</p></div></footer>; }

function ProductImage({ product, className = '' }: { product: Product; className?: string }) {
  const [index, setIndex] = useState(0); const images = product.images?.filter(Boolean) || [];
  return <div className={`relative flex items-center justify-center overflow-hidden ${className}`}><img src={images[index] || fallbackPhoto} alt={product.name} className="product-img h-full w-full object-contain p-7" onError={(e) => { e.currentTarget.src = fallbackPhoto; }} data-testid={`img-product-${product.id}`}/>{images.length > 1 && <div className="absolute bottom-3 right-3 flex gap-1.5">{images.slice(0,4).map((_,i)=><button key={i} aria-label={`Show product image ${i+1}`} onClick={()=>setIndex(i)} className={`h-1.5 rounded-full transition-all ${i===index?'w-6 bg-[#2469c9]':'w-1.5 bg-[#b7c8d9]'}`} />)}</div>}</div>;
}
const apiStatus = (error: unknown) => typeof error === 'object' && error !== null && 'status' in error ? Number((error as {status:unknown}).status) : 0;

function ProductCard({ product, compared, onCompare, onAdd }: { product: Product; compared: boolean; onCompare: (id: string)=>void; onAdd: (id: string)=>void }) {
  return <article className="catalog-card group overflow-hidden rounded-2xl" data-testid={`card-product-${product.id}`}>
    <Link href={`/product/${product.id}`} className="block">
      <div className="product-visual relative h-56 sm:h-60"><ProductImage product={product}/>{product.featured && <span className="absolute left-4 top-4 rounded-full bg-white/90 px-3 py-1.5 text-[10px] font-bold uppercase tracking-[.12em] text-[#28639e]">Staff pick</span>}<span className="absolute right-4 top-4 rounded-full border border-white/80 bg-white/75 px-2.5 py-1 text-[10px] font-medium text-[#506981]">{product.stock > 0 ? 'In stock' : 'Sold out'}</span></div>
      <div className="px-5 pt-4"><p className="eyebrow">{product.brand} <span className="mx-1 text-[#a3b5c8]">/</span> {product.category}</p><h3 className="mt-2 min-h-[48px] text-[17px] font-semibold leading-6 text-[#1c2d42]">{product.name}</h3><p className="mt-2 line-clamp-2 min-h-10 text-sm leading-5 text-[#718196]">{product.description}</p></div>
    </Link>
    <div className="flex items-center justify-between px-5 pb-5 pt-4"><div><span className="mono text-lg font-bold text-[#173c69]">{money(product.price)}</span><span className="ml-2 text-[11px] text-[#8492a1]">one-time</span></div><button onClick={()=>onAdd(product.id)} disabled={product.stock < 1} className="flex h-10 w-10 items-center justify-center rounded-xl bg-[#eaf3fd] text-[#2364b3] hover:bg-[#2469c9] hover:text-white disabled:opacity-40" aria-label={`Add ${product.name} to bag`} data-testid={`button-add-${product.id}`}><Plus size={18}/></button></div>
    <div className="flex items-center justify-between border-t border-[#eef1f4] px-5 py-3"><button onClick={()=>onCompare(product.id)} className={`flex items-center gap-2 text-xs font-semibold ${compared?'text-[#2469c9]':'text-[#8291a1] hover:text-[#2469c9]'}`} data-testid={`button-compare-${product.id}`}><span className={`flex h-4 w-4 items-center justify-center rounded border ${compared?'border-[#2469c9] bg-[#2469c9] text-white':'border-[#c6d1dc]'}`}>{compared&&<Check size={11}/>}</span>{compared?'Added to compare':'Compare specs'}</button><Link href={`/product/${product.id}`} className="flex items-center gap-1 text-xs font-semibold text-[#56728f] hover:text-[#2469c9]">Details <ArrowUpRight size={14}/></Link></div>
  </article>;
}

function Home() {
  const { data: products, isLoading, isError, refetch } = useGetProducts();
  const [search,setSearch] = useState(''); const [category,setCategory] = useState('All laptops'); const [sort,setSort] = useState('featured'); const [compare,setCompare] = useState<string[]>([]); const [cart,setCart] = useState<CartLine[]>(readCart); const [heroIndex,setHeroIndex] = useState(0);
  useEffect(()=>{const t=window.setInterval(()=>setHeroIndex(v=>(v+1)%3),5200);return()=>window.clearInterval(t)},[]);
  const categories = useMemo(()=>['All laptops',...Array.from(new Set((products||[]).map(p=>p.category).filter(Boolean)))],[products]);
  const filtered = useMemo(()=>{let result=(products||[]).filter(p=>(category==='All laptops'||p.category===category)&&(`${p.name} ${p.brand} ${p.description}`).toLowerCase().includes(search.toLowerCase()));return result.sort((a,b)=>sort==='price-low'?a.price-b.price:sort==='price-high'?b.price-a.price:sort==='name'?a.name.localeCompare(b.name):Number(b.featured)-Number(a.featured));},[products,category,search,sort]);
  const heroProduct = products?.length ? products[heroIndex % products.length] : undefined;
  const heroImage = heroProduct?.images?.[0] || heroLaptops;
  const setCartAndSave=(next:CartLine[])=>{setCart(next);localStorage.setItem(CART_KEY,JSON.stringify(next));};
  const add=(id:string)=>{const line=cart.find(c=>c.productId===id);setCartAndSave(line?cart.map(c=>c.productId===id?{...c,quantity:c.quantity+1}:c):[...cart,{productId:id,quantity:1}]);};
  const toggleCompare=(id:string)=>setCompare(c=>c.includes(id)?c.filter(x=>x!==id):c.length<3?[...c,id]:c);
  const compared=(products||[]).filter(p=>compare.includes(p.id));
  return <div className="site-wrap"><Header cartCount={cart.reduce((n,l)=>n+l.quantity,0)}/><main>
    <section className="mx-auto max-w-7xl px-5 pt-6 lg:px-8"><div className="hero-panel min-h-[430px] rounded-[28px] px-7 py-10 md:min-h-[460px] md:px-12 md:py-14">
      <img className="hero-art" src={heroImage} alt={heroProduct ? `${heroProduct.name} laptop` : 'A selection of premium laptops on a cool studio surface'} onError={e=>{e.currentTarget.src=heroLaptops}}/>
      <div className="hero-copy flex min-h-[350px] max-w-[540px] flex-col justify-center md:min-h-[350px]"><p className="eyebrow flex items-center gap-2"><span className="h-px w-7 bg-[#5688bd]"/>A better way to choose</p><h1 className="serif-display mt-5 text-[52px] leading-[.98] text-[#173c69] sm:text-[64px] md:text-[72px]">{['Your next idea deserves a great machine.','Find the fit. Then get to it.','More clarity. Better computing.'][heroIndex]}</h1><p className="mt-5 max-w-[380px] text-[15px] leading-7 text-[#576f89]">Compare the details that matter, see every angle, and choose a laptop that feels right for the way you work and live.</p><div className="mt-7 flex flex-wrap gap-3"><a href="#catalog" className="btn-primary flex items-center gap-2 rounded-xl px-5 py-3 text-sm font-semibold shadow-sm">Explore the lineup <ArrowRight size={16}/></a><a href="#compare" className="btn-outline rounded-xl px-5 py-3 text-sm font-semibold">Compare models</a></div><div className="mt-7 flex gap-2">{[0,1,2].map(i=><button key={i} onClick={()=>setHeroIndex(i)} aria-label={`Show showcase slide ${i+1}`} className={`h-1 rounded-full transition-all ${heroIndex===i?'w-8 bg-[#2469c9]':'w-4 bg-[#aebfd1]'}`}/>)}</div></div>
      <div className="absolute bottom-5 right-8 z-10 hidden items-center gap-2 text-[10px] font-semibold uppercase tracking-[.14em] text-[#6d8299] md:flex"><span className="h-1.5 w-1.5 rounded-full bg-[#48a385]"/>A considered collection</div>
    </div></section>
    <section className="mx-auto max-w-7xl px-5 pt-14 lg:px-8" id="catalog"><div className="flex flex-col justify-between gap-5 md:flex-row md:items-end"><div><p className="eyebrow">The lineup</p><h2 className="serif-display mt-2 text-4xl text-[#173c69] md:text-[48px]">Meet your next laptop.</h2><p className="mt-2 max-w-xl text-sm leading-6 text-[#748498]">Every pick has a clear spec sheet, honest availability, and room to compare before you decide.</p></div><div className="flex items-center gap-2 self-start rounded-full border border-[#dce4ec] bg-white px-3 py-2 text-xs text-[#63768a] md:self-auto"><ShieldCheck size={15} className="text-[#438c78]"/>Guest checkout · No account needed</div></div>
      <div className="mt-7 flex flex-col gap-3 border-y border-[#dce4ec] py-4 md:flex-row md:items-center md:justify-between"><div className="flex flex-1 flex-wrap gap-2">{categories.map(c=><button key={c} onClick={()=>setCategory(c)} className={`rounded-full px-4 py-2 text-xs font-semibold ${category===c?'bg-[#173c69] text-white':'bg-white text-[#61768b] hover:bg-[#eaf3fd]'}`}>{c}</button>)}</div><div className="flex gap-2"><label className="relative min-w-[190px] flex-1 md:flex-none"><Search className="absolute left-3 top-1/2 -translate-y-1/2 text-[#91a0ae]" size={15}/><input aria-label="Search laptops" value={search} onChange={e=>setSearch(e.target.value)} placeholder="Search laptops" className="input-field !rounded-full !py-2.5 !pl-9 !text-xs" data-testid="input-search-products"/></label><label className="relative"><SlidersHorizontal className="pointer-events-none absolute left-3 top-1/2 -translate-y-1/2 text-[#8494a4]" size={14}/><select aria-label="Sort products" value={sort} onChange={e=>setSort(e.target.value)} className="input-field !w-auto !rounded-full !py-2.5 !pl-9 !pr-7 !text-xs" data-testid="select-sort"><option value="featured">Featured first</option><option value="price-low">Price: low to high</option><option value="price-high">Price: high to low</option><option value="name">Name A–Z</option></select></label></div></div>
      {isLoading?<div className="grid gap-5 pt-6 sm:grid-cols-2 lg:grid-cols-3">{[0,1,2].map(i=><div key={i} className="overflow-hidden rounded-2xl border border-[#e0e7ef] bg-white"><div className="skeleton h-56"/><div className="space-y-3 p-5"><div className="skeleton h-3 w-24 rounded"/><div className="skeleton h-5 w-3/4 rounded"/><div className="skeleton h-4 w-full rounded"/></div></div>)}</div>:isError?<div className="my-8 rounded-2xl border border-[#e4c7c5] bg-[#fff9f8] p-8 text-center"><p className="font-semibold text-[#7c3531]">We couldn’t load the lineup.</p><p className="mt-1 text-sm text-[#8d6c69]">Please try again in a moment.</p><button onClick={()=>refetch()} className="btn-outline mt-4 rounded-lg px-4 py-2 text-sm">Try again</button></div>:filtered.length===0?<div className="my-8 rounded-2xl border border-dashed border-[#cdd9e5] bg-white px-6 py-14 text-center"><Search className="mx-auto text-[#92a6ba]" size={28}/><h3 className="mt-3 font-semibold text-[#28425d]">No laptops match that search.</h3><p className="mt-1 text-sm text-[#8090a0]">Try another name, brand, or category.</p><button onClick={()=>{setSearch('');setCategory('All laptops')}} className="mt-4 text-sm font-semibold text-[#2469c9]">Clear filters</button></div>:<div className="grid gap-5 pt-6 sm:grid-cols-2 lg:grid-cols-3">{filtered.map((p,i)=><div key={p.id} className="fade-in" style={{animationDelay:`${Math.min(i*70,350)}ms`}}><ProductCard product={p} compared={compare.includes(p.id)} onCompare={toggleCompare} onAdd={add}/></div>)}</div>}
    </section>
    <section id="compare" className="mx-auto max-w-7xl px-5 pt-16 lg:px-8"><div className="rounded-[24px] bg-[#eaf1f8] p-6 md:p-9"><div className="flex flex-col justify-between gap-5 md:flex-row md:items-end"><div><p className="eyebrow">Side by side</p><h2 className="serif-display mt-2 text-4xl text-[#173c69]">A clearer comparison.</h2><p className="mt-2 text-sm text-[#708196]">Choose up to three laptops above to line up their key details.</p></div><a href="#catalog" className="flex items-center gap-2 text-sm font-semibold text-[#2469c9]">Choose laptops <ArrowUpRight size={15}/></a></div>
      {compared.length===0?<div className="mt-6 flex min-h-[100px] items-center gap-4 rounded-2xl border border-dashed border-[#c0d0df] bg-white/60 px-5"><Layers3 className="text-[#7e9ab5]" size={24}/><p className="text-sm text-[#74879b]">Your comparison table will appear here. Start with any laptop in the lineup.</p></div>:<div className="mt-6 overflow-x-auto rounded-2xl border border-[#d8e2eb] bg-white"><table className="w-full min-w-[680px] text-left text-sm"><thead><tr><th className="w-36 px-5 py-4 text-xs font-semibold uppercase tracking-wider text-[#8191a1]">At a glance</th>{compared.map(p=><th key={p.id} className="px-5 py-4 text-[#213d5b]">{p.name}<button aria-label={`Remove ${p.name} from comparison`} onClick={()=>toggleCompare(p.id)} className="ml-2 text-[#8b9bab] hover:text-red-600"><X size={14}/></button></th>)}</tr></thead><tbody>{[['Price',(p:Product)=>money(p.price)],['Category',(p:Product)=>p.category],...Array.from(new Set(compared.flatMap(p=>Object.keys(p.specs||{})))).slice(0,5).map(key=>[key,(p:Product)=>p.specs?.[key]||'—'] as [string,(p:Product)=>string]),['Availability',(p:Product)=>p.stock>0?`${p.stock} available`:'Currently unavailable']].map(([label,getValue])=><tr key={label as string} className="border-t border-[#edf1f4]"><td className="px-5 py-3 text-xs font-semibold text-[#8493a2]">{label as string}</td>{compared.map(p=><td key={p.id} className="px-5 py-3 font-medium text-[#37516b]">{(getValue as (p:Product)=>string)(p)}</td>)}</tr>)}</tbody></table></div>}
    </div></section>
    <section id="guidance" className="mx-auto max-w-7xl px-5 pt-16 lg:px-8"><div className="grid gap-5 md:grid-cols-[1.05fr_.95fr]"><div className="rounded-[24px] bg-[#173c69] p-7 text-white md:p-10"><p className="eyebrow !text-[#a9ccef]">A little guidance</p><h2 className="serif-display mt-3 max-w-lg text-4xl leading-tight md:text-[46px]">The best laptop is the one that fits your day.</h2><p className="mt-4 max-w-md text-sm leading-6 text-[#c1d4e8]">Start with what you’ll do most. Then compare memory, storage, and screen details across the models that catch your eye.</p><a href="#catalog" className="mt-6 inline-flex items-center gap-2 rounded-xl bg-white px-4 py-3 text-sm font-semibold text-[#173c69] hover:bg-[#eaf3fd]">Browse the lineup <ArrowRight size={16}/></a></div><div className="grid grid-cols-2 gap-3">{[{icon:<Cpu/>,title:'Performance',text:'Look for the processor and memory that match your workload.'},{icon:<HardDrive/>,title:'Room to grow',text:'Storage capacity matters for large libraries and creative work.'},{icon:<Truck/>,title:'Easy delivery',text:'Order as a guest with clear contact and delivery details.'},{icon:<CircleHelp/>,title:'Compare calmly',text:'Put up to three models side by side before you choose.'}].map(item=><div key={item.title} className="rounded-2xl border border-[#dce4ec] bg-white p-5"><span className="text-[#3172bd]">{item.icon}</span><h3 className="mt-3 text-sm font-bold text-[#27425e]">{item.title}</h3><p className="mt-1.5 text-xs leading-5 text-[#7a8a9b]">{item.text}</p></div>)}</div></div></section>
  </main><Footer/></div>;
}

function ProductPage() {
  const { productId='' }=useParams<{productId:string}>(); const {data:product,isLoading,isError,refetch}=useGetProduct(productId); const {data:similar}=useGetSimilarProducts(productId); const [cart,setCart]=useState<CartLine[]>(readCart);const [imageIndex,setImageIndex]=useState(0);const [chatOpen,setChatOpen]=useState(false);const [question,setQuestion]=useState('');const [reply,setReply]=useState('');const chat=useChatAboutProduct();const [chatError,setChatError]=useState('');
  const add=()=>{if(!product)return;const existing=cart.find(x=>x.productId===product.id);const next=existing?cart.map(x=>x.productId===product.id?{...x,quantity:x.quantity+1}:x):[...cart,{productId:product.id,quantity:1}];setCart(next);localStorage.setItem(CART_KEY,JSON.stringify(next));};
  const sendQuestion=()=>{if(!product||!question.trim())return;setChatError('');setReply('');chat.mutate({data:{productId:product.id,message:question.trim()}},{onSuccess:r=>setReply(r.reply),onError:error=>setChatError(apiStatus(error)===503?'Product chat setup is required. The server returned HTTP 503 because Cohere is not configured. No answer was generated.':'Product chat could not reach the configured service. Please try again later.')});};
  return <div className="site-wrap"><Header cartCount={cart.reduce((n,x)=>n+x.quantity,0)}/><main className="mx-auto max-w-7xl px-5 py-8 lg:px-8"><Link href="/" className="mb-6 inline-flex items-center gap-2 text-sm font-semibold text-[#6e8195] hover:text-[#2469c9]"><ArrowLeft size={16}/>Back to all laptops</Link>
    {isLoading?<div className="grid gap-8 md:grid-cols-2"><div className="skeleton h-[420px] rounded-3xl"/><div className="space-y-4"><div className="skeleton h-4 w-32 rounded"/><div className="skeleton h-10 w-3/4 rounded"/><div className="skeleton h-28 rounded"/></div></div>:isError||!product?<div className="rounded-2xl bg-white p-12 text-center"><h1 className="text-xl font-bold">This laptop isn’t available right now.</h1><button onClick={()=>refetch()} className="btn-outline mt-4 rounded-lg px-4 py-2">Try again</button></div>:<>
      <div className="grid gap-8 lg:grid-cols-[1.08fr_.92fr]"><div><div className="product-visual relative flex h-[360px] items-center justify-center overflow-hidden rounded-[26px] sm:h-[480px]"><img src={product.images?.[imageIndex]||fallbackPhoto} alt={product.name} className="h-full w-full object-contain p-8" onError={e=>{e.currentTarget.src=fallbackPhoto}}/><button onClick={()=>setImageIndex((imageIndex+product.images.length-1)%Math.max(product.images.length,1))} aria-label="Previous product photo" className="absolute left-4 top-1/2 flex h-10 w-10 -translate-y-1/2 items-center justify-center rounded-full bg-white/90 text-[#355575] shadow-sm"><ChevronLeft size={18}/></button><button onClick={()=>setImageIndex((imageIndex+1)%Math.max(product.images.length,1))} aria-label="Next product photo" className="absolute right-4 top-1/2 flex h-10 w-10 -translate-y-1/2 items-center justify-center rounded-full bg-white/90 text-[#355575] shadow-sm"><ChevronRight size={18}/></button><span className="absolute bottom-4 right-4 rounded-full bg-white/85 px-3 py-1.5 text-xs text-[#62778e]">{imageIndex+1} / {Math.max(product.images?.length||0,1)}</span></div><div className="mt-3 flex gap-3">{(product.images?.length?product.images:[fallbackPhoto]).slice(0,5).map((img,i)=><button key={img+i} onClick={()=>setImageIndex(i)} className={`product-visual h-[72px] w-[82px] overflow-hidden rounded-xl border-2 ${i===imageIndex?'border-[#2469c9]':'border-transparent'}`}><img src={img||fallbackPhoto} alt={`${product.name} view ${i+1}`} className="h-full w-full object-contain p-2"/></button>)}</div></div>
        <div className="pt-1"><p className="eyebrow">{product.brand} / {product.category}</p><h1 className="serif-display mt-3 text-5xl leading-[1.02] text-[#173c69]">{product.name}</h1><p className="mt-5 max-w-xl text-[15px] leading-7 text-[#718196]">{product.description}</p><div className="mt-6 flex items-end gap-3"><span className="mono text-3xl font-bold text-[#173c69]">{money(product.price)}</span><span className="mb-1 text-xs text-[#8594a3]">one-time payment</span></div><div className="mt-4 flex items-center gap-2 text-sm"><span className={`h-2 w-2 rounded-full ${product.stock>0?'bg-[#43a487]':'bg-[#c56860]'}`}/><span className="font-semibold text-[#4a637c]">{product.stock>0?`${product.stock} available`:'Currently unavailable'}</span></div><div className="mt-6 flex flex-wrap gap-3"><button onClick={add} disabled={product.stock<1} className="btn-primary flex items-center justify-center gap-2 rounded-xl px-6 py-3.5 text-sm font-semibold disabled:opacity-50"><ShoppingBag size={17}/>Add to bag</button><button onClick={()=>setChatOpen(true)} className="btn-outline flex items-center gap-2 rounded-xl px-5 py-3.5 text-sm font-semibold"><Sparkles size={16}/>Ask about this laptop</button></div><div className="mt-7 flex flex-wrap gap-x-6 gap-y-3 border-y border-[#e5ebf1] py-4 text-xs text-[#667d94]"><span className="flex items-center gap-2"><PackageCheck size={15} className="text-[#428b78]"/>Guest checkout</span><span className="flex items-center gap-2"><ShieldCheck size={15} className="text-[#428b78]"/>No account required</span><span className="flex items-center gap-2"><Truck size={15} className="text-[#428b78]"/>Delivery details at checkout</span></div></div></div>
      <section className="mt-14"><div className="flex items-end justify-between"><div><p className="eyebrow">The details</p><h2 className="serif-display mt-2 text-4xl text-[#173c69]">Specifications.</h2></div><span className="hidden text-xs text-[#8794a3] sm:block">Clear facts, no fine-print hunt.</span></div><div className="mt-5 grid gap-3 sm:grid-cols-2 lg:grid-cols-3">{Object.entries(product.specs||{}).map(([key,value],i)=><div key={key} className="flex items-start justify-between gap-4 rounded-xl border border-[#e0e7ef] bg-white p-4"><span className="text-xs font-medium capitalize text-[#7b8b9b]">{key.replace(/([A-Z])/g,' $1')}</span><span className="text-right text-sm font-semibold text-[#294966]">{value}</span></div>)}{Object.keys(product.specs||{}).length===0&&<p className="text-sm text-[#75869a]">Specifications will be added soon.</p>}</div></section>
      {similar&&similar.length>0&&<section className="mt-14"><p className="eyebrow">Worth a look</p><h2 className="serif-display mt-2 text-4xl text-[#173c69]">Similar machines.</h2><div className="mt-5 grid gap-4 sm:grid-cols-2 lg:grid-cols-3">{similar.slice(0,3).map(p=><Link key={p.id} href={`/product/${p.id}`} className="catalog-card flex items-center gap-4 rounded-2xl p-4"><div className="product-visual h-24 w-28 shrink-0 rounded-xl"><ProductImage product={p}/></div><div><p className="eyebrow">{p.brand}</p><h3 className="mt-1 text-sm font-semibold text-[#28435e]">{p.name}</h3><p className="mono mt-2 text-sm font-bold text-[#173c69]">{money(p.price)}</p></div><ArrowUpRight size={15} className="ml-auto text-[#91a2b3]"/></Link>)}</div></section>}
    </>}
  </main><Footer/>{chatOpen&&product&&<div className="drawer-backdrop fixed inset-0 z-50 flex items-end justify-center p-0 sm:items-center sm:p-5" onClick={()=>setChatOpen(false)}><section role="dialog" aria-modal="true" aria-label="Ask about this laptop" onClick={e=>e.stopPropagation()} className="w-full max-w-lg rounded-t-[24px] bg-white p-6 shadow-2xl sm:rounded-[24px]"><div className="flex items-start justify-between"><div><p className="eyebrow">Product guide</p><h2 className="serif-display mt-1 text-3xl text-[#173c69]">Ask about this laptop.</h2><p className="mt-1 text-sm text-[#7b8a99]">{product.name}</p></div><button onClick={()=>setChatOpen(false)} className="rounded-full p-2 text-[#77899a] hover:bg-[#edf3f8]" aria-label="Close chat"><X size={18}/></button></div><div className="mt-5 rounded-xl bg-[#f0f5fa] p-4 text-sm leading-6 text-[#647990]">Ask about performance, portability, or how the listed specs fit your needs. Answers use the product details shown here.</div>{reply&&<div className="mt-4 rounded-xl border border-[#d8e7f5] bg-[#f7fbff] p-4 text-sm leading-6 text-[#34536f]" data-testid="text-chat-reply">{reply}</div>}{chatError&&<div className="mt-4 rounded-xl border border-[#e6d7ba] bg-[#fffaf0] p-4 text-sm leading-6 text-[#725a2a]" role="status">{chatError}</div>}<form className="mt-4" onSubmit={e=>{e.preventDefault();sendQuestion()}}><textarea value={question} onChange={e=>setQuestion(e.target.value)} placeholder="What would you like to know?" rows={3} className="input-field resize-none" data-testid="input-chat-question"/><button disabled={!question.trim()||chat.isPending} className="btn-primary mt-3 flex w-full items-center justify-center gap-2 rounded-xl px-4 py-3 text-sm font-semibold disabled:opacity-50">{chat.isPending?'Checking product details…':'Ask question'}<ArrowRight size={16}/></button></form></section></div>}</div>;
}

function Checkout() {
  const [cart,setCart]=useState<CartLine[]>(readCart);const [customer,setCustomer]=useState({name:'',email:'',phone:'',deliveryAddress:''});const [complete,setComplete]=useState<null|{reference:string,total:number}>(null);const {data:products}=useGetProducts();const order=useCreateGuestOrder();
  const lines=cart.map(line=>({line,product:products?.find(p=>p.id===line.productId)})).filter(x=>x.product);const total=lines.reduce((sum,x)=>sum+(x.product?.price||0)*x.line.quantity,0);
  const changeQty=(id:string,delta:number)=>{const next=cart.map(x=>x.productId===id?{...x,quantity:x.quantity+delta}:x).filter(x=>x.quantity>0);setCart(next);localStorage.setItem(CART_KEY,JSON.stringify(next));};
  const submit=(e:React.FormEvent)=>{e.preventDefault();if(!lines.length)return;const payload:GuestOrderInput={...customer,items:lines.map(({line})=>line)};order.mutate({data:payload},{onSuccess:r=>{localStorage.removeItem(CART_KEY);setCart([]);setComplete({reference:r.reference,total:r.total});}});};
  return <div className="site-wrap"><Header cartCount={cart.reduce((n,x)=>n+x.quantity,0)}/><main className="mx-auto max-w-7xl px-5 py-10 lg:px-8"><Link href="/" className="inline-flex items-center gap-2 text-sm font-semibold text-[#6e8195] hover:text-[#2469c9]"><ArrowLeft size={16}/>Continue shopping</Link><div className="mt-6 grid gap-10 lg:grid-cols-[1fr_390px]"><section><p className="eyebrow">A simple finish</p><h1 className="serif-display mt-2 text-5xl text-[#173c69]">Guest checkout.</h1><p className="mt-3 max-w-xl text-sm leading-6 text-[#75869a]">No account to create. Just leave the details needed to arrange your order.</p>
      {complete?<div className="mt-7 rounded-2xl border border-[#c7e1d7] bg-[#f3fbf7] p-7" data-testid="status-order-confirmed"><span className="flex h-11 w-11 items-center justify-center rounded-full bg-[#d7eee5] text-[#34836b]"><Check size={20}/></span><h2 className="mt-4 text-xl font-bold text-[#284c40]">Order request received.</h2><p className="mt-2 text-sm leading-6 text-[#638174]">Reference <span className="mono font-bold">{complete.reference}</span> is saved. Payment has not been collected because a payment provider is not connected yet. The store will follow up to confirm next steps.</p><Link href="/" className="mt-5 inline-flex items-center gap-2 text-sm font-semibold text-[#2469c9]">Back to the showroom <ArrowRight size={15}/></Link></div>:<form onSubmit={submit} className="mt-7 space-y-4"><div className="grid gap-4 sm:grid-cols-2"><label className="text-xs font-semibold text-[#4c6278]">Full name<input required value={customer.name} onChange={e=>setCustomer({...customer,name:e.target.value})} className="input-field mt-2" placeholder="Your name" data-testid="input-customer-name"/></label><label className="text-xs font-semibold text-[#4c6278]">Email address<input required type="email" value={customer.email} onChange={e=>setCustomer({...customer,email:e.target.value})} className="input-field mt-2" placeholder="you@example.com" data-testid="input-customer-email"/></label><label className="text-xs font-semibold text-[#4c6278]">Phone number<input required type="tel" value={customer.phone} onChange={e=>setCustomer({...customer,phone:e.target.value})} className="input-field mt-2" placeholder="Best number to reach you" data-testid="input-customer-phone"/></label><label className="text-xs font-semibold text-[#4c6278] sm:col-span-2">Delivery address<textarea required rows={3} value={customer.deliveryAddress} onChange={e=>setCustomer({...customer,deliveryAddress:e.target.value})} className="input-field mt-2 resize-y" placeholder="Street, city, postal code" data-testid="input-delivery-address"/></label></div><div className="rounded-xl border border-[#e5d6b6] bg-[#fffaf0] p-4 text-sm leading-6 text-[#735c30]"><span className="font-semibold">Payment is not collected at this stage.</span> No payment provider is connected. We’ll confirm your order details with you before arranging payment.</div>{order.isError&&<p role="alert" className="text-sm text-[#a9443d]">We couldn’t submit your order. Please review your details and try again.</p>}<button disabled={order.isPending||!lines.length} className="btn-primary flex w-full items-center justify-center gap-2 rounded-xl px-5 py-3.5 text-sm font-semibold disabled:opacity-50" data-testid="button-submit-order">{order.isPending?'Sending order request…':'Place order request'}<ArrowRight size={16}/></button></form>}</section>
      <aside className="h-fit rounded-2xl border border-[#dfe7ee] bg-white p-5"><p className="eyebrow">Your selection</p><h2 className="mt-2 text-lg font-bold text-[#26425f]">Order summary</h2>{lines.length===0?<div className="mt-5 rounded-xl bg-[#f4f7fa] p-5 text-center"><ShoppingBag className="mx-auto text-[#97a7b5]" size={24}/><p className="mt-2 text-sm text-[#75869a]">Your bag is still empty.</p><Link href="/" className="mt-3 inline-block text-sm font-semibold text-[#2469c9]">Find a laptop</Link></div>:<div className="mt-4 divide-y divide-[#edf1f4]">{lines.map(({line,product})=><div key={line.productId} className="flex gap-3 py-4"><div className="product-visual h-[68px] w-[78px] shrink-0 rounded-lg"><ProductImage product={product!}/></div><div className="min-w-0 flex-1"><p className="line-clamp-2 text-sm font-semibold text-[#304a64]">{product?.name}</p><p className="mono mt-1 text-sm font-bold text-[#173c69]">{money((product?.price||0)*line.quantity)}</p><div className="mt-2 flex items-center gap-2"><button aria-label="Decrease quantity" onClick={()=>changeQty(line.productId,-1)} className="rounded border border-[#dce4ec] p-1 text-[#647a91]"><Minus size={12}/></button><span className="mono text-xs">{line.quantity}</span><button aria-label="Increase quantity" onClick={()=>changeQty(line.productId,1)} className="rounded border border-[#dce4ec] p-1 text-[#647a91]"><Plus size={12}/></button><button onClick={()=>changeQty(line.productId,-line.quantity)} className="ml-auto text-xs text-[#8493a2] hover:text-red-600">Remove</button></div></div></div>)}</div>}<div className="mt-4 flex justify-between border-t border-[#e5ebf1] pt-4"><span className="text-sm font-semibold text-[#61758a]">Estimated total</span><span className="mono text-lg font-bold text-[#173c69]">{money(total)}</span></div><p className="mt-2 text-[11px] leading-5 text-[#8997a5]">Delivery and payment arrangements will be confirmed with you.</p></aside>
    </div></main><Footer/></div>;
}

function AdminPage() {
  const qc=useQueryClient();const {data:products,isLoading:pLoading,isError:pError,error:pQueryError}=useGetAdminProducts({query:{enabled:true,queryKey:getGetAdminProductsQueryKey(),retry:false}});const {data:orders,isLoading:oLoading,isError:oError,error:oQueryError}=useGetAdminOrders({query:{enabled:true,queryKey:getGetAdminOrdersQueryKey(),retry:false}});const create=useCreateAdminProduct();const update=useUpdateAdminProduct();const remove=useDeleteAdminProduct();const [tab,setTab]=useState<'products'|'orders'>('products');const [editing,setEditing]=useState<Product|null>(null);const [isNew,setIsNew]=useState(false);const [message,setMessage]=useState('');const [uploading,setUploading]=useState(false);const {signOut}=useClerk();const {user}=useUser();
  const blank:ProductInput={name:'',brand:'',category:'',price:0,description:'',images:[],specs:{},stock:0,featured:false};
  const [form,setForm]=useState<ProductInput>(blank);
  const openNew=()=>{setIsNew(true);setEditing(null);setForm(blank);setMessage('');};
  const openEdit=(p:Product)=>{setIsNew(false);setEditing(p);setForm({name:p.name,brand:p.brand,category:p.category,price:p.price,description:p.description,images:p.images||[],specs:p.specs||{},stock:p.stock,featured:p.featured});setMessage('');};
  const save=(e:React.FormEvent)=>{e.preventDefault();const payload={...form,images:form.images.map(x=>x.trim()).filter(Boolean),specs:Object.fromEntries(Object.entries(form.specs).filter(([k,v])=>k.trim()&&v.trim()))};const done=()=>{void qc.invalidateQueries({queryKey:getGetAdminProductsQueryKey()});void qc.invalidateQueries({queryKey:getGetProductsQueryKey()});setEditing(null);setIsNew(false);setMessage('Product saved.');};if(isNew)create.mutate({data:payload},{onSuccess:done,onError:()=>setMessage('Product could not be saved. Confirm admin access is configured.')});else if(editing)update.mutate({productId:editing.id,data:payload},{onSuccess:done,onError:()=>setMessage('Product could not be saved. Confirm admin access is configured.')});};
  const del=(p:Product)=>{if(window.confirm(`Remove ${p.name} from the catalog?`))remove.mutate({productId:p.id},{onSuccess:()=>{void qc.invalidateQueries({queryKey:getGetAdminProductsQueryKey()});void qc.invalidateQueries({queryKey:getGetProductsQueryKey()});},onError:()=>setMessage('Product could not be removed. Confirm admin access is configured.')});};
  const setSpec=(key:string,value:string)=>setForm(f=>({...f,specs:{...f.specs,[key]:value}}));
  const uploadImage=async(file:File)=>{setUploading(true);setMessage('');try{const body=new FormData();body.append('image',file);const response=await fetch('/api/admin/images',{method:'POST',credentials:'include',body});const result=await response.json() as Record<string,unknown>;if(!response.ok){if(response.status===503)throw new Error('Admin setup is not ready. Configure the server-side ADMIN_EMAIL allowlist before uploading.');throw new Error(typeof result.error==='string'?result.error:'Image upload failed.');}const url=typeof result.url==='string'?result.url:typeof result.imageUrl==='string'?result.imageUrl:typeof result.image==='string'?result.image:'';if(!url)throw new Error('The upload completed but the server did not return an image URL.');setForm(f=>({...f,images:[...f.images,url]}));setMessage('Image uploaded and added to this product.');}catch(error){setMessage(error instanceof Error?error.message:'Image upload failed.');}finally{setUploading(false);}};
  if(pLoading||oLoading)return <div className="site-wrap"><Header/><main className="mx-auto max-w-7xl px-5 py-10 lg:px-8"><div className="skeleton h-10 w-64 rounded"/><div className="mt-7 grid gap-4"><div className="skeleton h-24 rounded-2xl"/><div className="skeleton h-64 rounded-2xl"/></div></main><Footer/></div>;
  if(pError||oError){const failedError=pError?pQueryError:oQueryError;const status=apiStatus(failedError);const setup=status===503;return <div className="site-wrap"><Header/><main className="mx-auto max-w-4xl px-5 py-10"><Link href="/" className="inline-flex items-center gap-2 text-sm font-semibold text-[#6e8195]"><ArrowLeft size={16}/>Back to storefront</Link><div className="mt-8 rounded-2xl border border-[#e6d9bb] bg-[#fffaf0] p-7"><span className="flex h-10 w-10 items-center justify-center rounded-xl bg-[#f3e8cb] text-[#967439]"><ShieldCheck size={20}/></span><h1 className="mt-4 text-xl font-bold text-[#584a2f]">{setup?'Admin setup is required.':'This account cannot access store management.'}</h1><p className="mt-2 text-sm leading-6 text-[#786844]">{setup?'The server has not configured ADMIN_EMAIL yet. Admin product and order data remains unavailable until the allowlist is set.':'The server did not authorize this account for store management. Only the configured admin email can access products and orders.'}</p><p className="mono mt-4 text-xs text-[#8a774f]">{setup?'HTTP 503 · ADMIN_EMAIL unset':`HTTP ${status||'—'} · admin access denied`}</p><button onClick={()=>signOut({redirectUrl:basePath||'/'})} className="btn-outline mt-5 flex items-center gap-2 rounded-lg px-4 py-2 text-sm font-semibold"><LogOut size={15}/>Sign out</button></div></main><Footer/></div>}
  return <div className="site-wrap"><Header/><main className="mx-auto max-w-7xl px-5 py-10 lg:px-8"><Link href="/" className="inline-flex items-center gap-2 text-sm font-semibold text-[#6e8195] hover:text-[#2469c9]"><ArrowLeft size={16}/>Back to storefront</Link><div className="mt-6 flex flex-wrap items-end justify-between gap-4"><div><p className="eyebrow">Store operations</p><h1 className="serif-display mt-2 text-5xl text-[#173c69]">Admin workspace.</h1><p className="mt-2 text-sm text-[#78899a]">Manage the catalog and review guest orders.</p></div><span className="rounded-full border border-[#dce4ec] bg-white px-3 py-2 text-xs text-[#718296]">Restricted area</span></div>
      <div className="flex items-center justify-end gap-3"><span className="text-xs text-[#73869a]">{user?.primaryEmailAddress?.emailAddress}</span><button onClick={()=>signOut({redirectUrl:basePath||'/'})} className="btn-outline flex items-center gap-2 rounded-lg px-3 py-2 text-xs font-semibold"><LogOut size={14}/>Sign out</button></div>
      <div className="admin-grid mt-4 gap-6"><aside className="h-fit rounded-2xl border border-[#dfe7ee] bg-white p-3"><button onClick={()=>setTab('products')} className={`flex w-full items-center gap-3 rounded-xl px-4 py-3 text-sm font-semibold ${tab==='products'?'bg-[#eaf3fd] text-[#2469c9]':'text-[#61758a] hover:bg-[#f4f7fa]'}`}><Laptop size={17}/>Products <span className="ml-auto text-xs">{products?.length||0}</span></button><button onClick={()=>setTab('orders')} className={`mt-1 flex w-full items-center gap-3 rounded-xl px-4 py-3 text-sm font-semibold ${tab==='orders'?'bg-[#eaf3fd] text-[#2469c9]':'text-[#61758a] hover:bg-[#f4f7fa]'}`}><ShoppingBag size={17}/>Guest orders <span className="ml-auto text-xs">{orders?.length||0}</span></button></aside>
        <section className="min-w-0 rounded-2xl border border-[#dfe7ee] bg-white p-5 md:p-7">{tab==='products'?<><div className="flex flex-wrap items-center justify-between gap-3"><div><p className="eyebrow">Catalog</p><h2 className="mt-1 text-xl font-bold text-[#28435e]">Products</h2></div><button onClick={openNew} className="btn-primary flex items-center gap-2 rounded-lg px-4 py-2.5 text-sm font-semibold"><Plus size={16}/>Add product</button></div>{message&&<p role="status" className="mt-4 text-sm text-[#43836d]">{message}</p>}{pLoading?<div className="mt-5 space-y-3">{[1,2,3].map(n=><div key={n} className="skeleton h-14 rounded-lg"/> )}</div>:pError?<div className="mt-5 rounded-xl bg-[#fff7f5] p-4 text-sm text-[#a14b43]">Could not load products. Check admin API access.</div>:<div className="mt-5 divide-y divide-[#edf1f4]">{(products||[]).map(p=><div key={p.id} className="flex flex-wrap items-center gap-3 py-3"><div className="product-visual h-14 w-16 rounded-lg"><ProductImage product={p}/></div><div className="min-w-0 flex-1"><p className="truncate text-sm font-semibold text-[#2b4661]">{p.name}</p><p className="mt-1 text-xs text-[#8694a2]">{p.brand} · {money(p.price)} · {p.stock} in stock</p></div><button onClick={()=>openEdit(p)} className="btn-outline rounded-lg px-3 py-2 text-xs font-semibold">Edit</button><button onClick={()=>del(p)} className="rounded-lg border border-[#eadad8] px-3 py-2 text-xs font-semibold text-[#a75149] hover:bg-[#fff7f5]">Remove</button></div>)}</div>}</>:<><p className="eyebrow">Guest orders</p><h2 className="mt-1 text-xl font-bold text-[#28435e]">Recent orders</h2>{oLoading?<div className="mt-5 space-y-3">{[1,2,3].map(n=><div key={n} className="skeleton h-16 rounded-lg"/> )}</div>:oError?<div className="mt-5 rounded-xl bg-[#fff7f5] p-4 text-sm text-[#a14b43]">Could not load orders. Check admin API access.</div>:!orders?.length?<div className="mt-5 rounded-xl border border-dashed border-[#d7e1ea] p-9 text-center text-sm text-[#8291a0]">No guest orders yet.</div>:<div className="mt-5 overflow-x-auto"><table className="w-full min-w-[620px] text-left text-sm"><thead className="border-b border-[#e8edf2] text-xs text-[#8593a1]"><tr><th className="py-3">Reference</th><th>Customer</th><th>Status</th><th>Payment</th><th className="text-right">Total</th></tr></thead><tbody>{orders.map(o=><tr key={o.id} className="border-b border-[#edf1f4]"><td className="mono py-4 text-xs font-bold text-[#375674]">{o.reference}</td><td><p className="font-semibold text-[#38516b]">{o.name}</p><p className="text-xs text-[#8593a1]">{o.email}</p></td><td><span className="rounded-full bg-[#edf3f8] px-2.5 py-1 text-xs text-[#5c7187]">{o.status}</span></td><td className="text-xs text-[#7e8d9a]">{o.paymentStatus}</td><td className="mono text-right font-bold text-[#254566]">{money(o.total)}</td></tr>)}</tbody></table></div>}</>}</section></div>
      {(isNew||editing)&&<div className="drawer-backdrop fixed inset-0 z-50 flex justify-end" onClick={()=>{setIsNew(false);setEditing(null)}}><section role="dialog" aria-modal="true" aria-label={isNew?'Add product':'Edit product'} onClick={e=>e.stopPropagation()} className="h-full w-full max-w-xl overflow-y-auto bg-white p-6 shadow-2xl"><div className="flex items-start justify-between"><div><p className="eyebrow">{isNew?'New listing':'Catalog edit'}</p><h2 className="serif-display mt-1 text-3xl text-[#173c69]">{isNew?'Add a laptop':'Edit laptop'}</h2></div><button onClick={()=>{setIsNew(false);setEditing(null)}} aria-label="Close product editor" className="rounded-full p-2 text-[#77899a] hover:bg-[#edf3f8]"><X size={18}/></button></div><form onSubmit={save} className="mt-6 space-y-4"><div className="grid grid-cols-2 gap-3">{[['name','Product name'],['brand','Brand'],['category','Category'],['price','Price'],['stock','Stock']].map(([key,label])=><label key={key} className={`text-xs font-semibold text-[#53697f] ${key==='name'?'col-span-2':''}`}>{label}<input required value={String(form[key as keyof ProductInput]??'')} type={key==='price'||key==='stock'?'number':'text'} min={key==='price'||key==='stock'?'0':undefined} step={key==='price'?'.01':undefined} onChange={e=>setForm({...form,[key]:key==='price'||key==='stock'?Number(e.target.value):e.target.value})} className="input-field mt-1.5" /></label>)}</div><label className="block text-xs font-semibold text-[#53697f]">Description<textarea required rows={3} value={form.description} onChange={e=>setForm({...form,description:e.target.value})} className="input-field mt-1.5 resize-y"/></label><label className="block text-xs font-semibold text-[#53697f]">Image URLs <span className="font-normal text-[#8b98a5]">(one per line)</span><textarea rows={4} value={form.images.join('\n')} onChange={e=>setForm({...form,images:e.target.value.split('\n')})} className="input-field mt-1.5 resize-y" placeholder="https://…"/></label><label className="block rounded-xl border border-dashed border-[#cbd9e6] bg-[#f7fafd] p-4 text-xs font-semibold text-[#53697f]">Upload a product image<input type="file" accept="image/*" disabled={uploading} onChange={e=>{const file=e.currentTarget.files?.[0];if(file)void uploadImage(file);e.currentTarget.value='';}} className="mt-2 block w-full text-xs font-normal file:mr-3 file:rounded-lg file:border-0 file:bg-[#e7f0fa] file:px-3 file:py-2 file:font-semibold file:text-[#2d5f98]" data-testid="input-admin-image-upload"/><span className="mt-2 block font-normal text-[#8593a1]">{uploading?'Uploading image securely…':'Uploads use the authenticated admin session.'}</span></label><div><p className="mb-2 text-xs font-semibold text-[#53697f]">Specifications</p><div className="space-y-2">{Object.entries(form.specs).map(([k,v],i)=><div key={k} className="flex gap-2"><input aria-label={`Specification name ${i+1}`} value={k} onChange={e=>{const next={...form.specs};delete next[k];next[e.target.value]=v;setForm({...form,specs:next})}} placeholder="Memory" className="input-field"/><input aria-label={`Specification value ${i+1}`} value={v} onChange={e=>setSpec(k,e.target.value)} placeholder="16 GB" className="input-field"/><button type="button" aria-label="Remove specification" onClick={()=>{const next={...form.specs};delete next[k];setForm({...form,specs:next})}} className="rounded-lg border border-[#e5eaf0] px-3 text-[#8190a0]"><X size={14}/></button></div>)}</div><button type="button" onClick={()=>setSpec(`spec_${Object.keys(form.specs).length+1}`,'')} className="mt-2 text-xs font-semibold text-[#2469c9]">+ Add specification</button></div><label className="flex items-center gap-2 text-sm text-[#53697f]"><input type="checkbox" checked={form.featured} onChange={e=>setForm({...form,featured:e.target.checked})} className="accent-[#2469c9]"/>Feature on storefront</label>{message&&<p role="status" className="text-sm text-[#a14b43]">{message}</p>}<button disabled={create.isPending||update.isPending||uploading} className="btn-primary w-full rounded-xl px-5 py-3 text-sm font-semibold disabled:opacity-50">{create.isPending||update.isPending?'Saving…':'Save product'}</button></form></section></div>}
  </main><Footer/></div>;
}

const clerkAppearance = {
  theme: shadcn,
  cssLayerName: 'clerk',
  options: {
    logoPlacement: 'inside' as const,
    logoLinkUrl: basePath || '/',
    logoImageUrl: `${window.location.origin}${basePath}/logo.svg`,
  },
  variables: {
    colorPrimary: '#2469c9',
    colorForeground: '#1c2d42',
    colorMutedForeground: '#68798d',
    colorDanger: '#b84d47',
    colorBackground: '#ffffff',
    colorInput: '#ffffff',
    colorInputForeground: '#20344b',
    colorNeutral: '#dce4ec',
    fontFamily: 'DM Sans',
    borderRadius: '0.75rem',
  },
  elements: {
    rootBox: 'w-full flex justify-center',
    cardBox: 'bg-white rounded-2xl w-[440px] max-w-full overflow-hidden shadow-xl',
    card: '!shadow-none !border-0 !bg-transparent !rounded-none',
    footer: '!shadow-none !border-0 !bg-transparent !rounded-none',
    headerTitle: 'text-[#173c69] font-semibold',
    headerSubtitle: 'text-[#68798d]',
    socialButtonsBlockButtonText: 'text-[#29435d] font-medium',
    formFieldLabel: 'text-[#435b73] font-medium',
    footerActionLink: 'text-[#2469c9] font-semibold',
    footerActionText: 'text-[#68798d]',
    dividerText: 'text-[#738397]',
    identityPreviewEditButton: 'text-[#2469c9]',
    formFieldSuccessText: 'text-[#34836b]',
    alertText: 'text-[#8b3935]',
    logoBox: 'mb-3',
    logoImage: 'max-h-12',
    socialButtonsBlockButton: 'border-[#dce4ec] hover:bg-[#f4f8fc]',
    formButtonPrimary: 'bg-[#2469c9] hover:bg-[#174f9b] text-white',
    formFieldInput: 'border-[#d6e0e9] bg-white text-[#20344b]',
    footerAction: 'mt-4',
    dividerLine: 'bg-[#dce4ec]',
    alert: 'border-[#ead1cf] bg-[#fff8f7]',
    otpCodeFieldInput: 'border-[#d6e0e9] bg-white text-[#20344b]',
    formFieldRow: 'mb-4',
    main: 'bg-transparent',
  },
};

function SignInPage() {
  return <main className="flex min-h-[100dvh] items-center justify-center bg-[#f1f5f9] px-4 py-10"><SignIn routing="path" path={`${basePath}/sign-in`} signUpUrl={`${basePath}/sign-up`} fallbackRedirectUrl={`${basePath}/admin`}/></main>;
}
function SignUpPage() {
  return <main className="flex min-h-[100dvh] items-center justify-center bg-[#f1f5f9] px-4 py-10"><SignUp routing="path" path={`${basePath}/sign-up`} signInUrl={`${basePath}/sign-in`} fallbackRedirectUrl={`${basePath}/admin`}/></main>;
}
function AdminRoute() {
  const {isLoaded,isSignedIn}=useUser();
  if(!isLoaded)return <div className="min-h-[100dvh] bg-[#f4f7fa] p-6"><div className="skeleton mx-auto mt-16 h-64 max-w-xl rounded-2xl"/></div>;
  if(!isSignedIn)return <div className="site-wrap"><Header/><main className="mx-auto max-w-3xl px-5 py-16"><div className="rounded-2xl border border-[#dce4ec] bg-white p-8 md:p-10"><p className="eyebrow">Store operations</p><h1 className="serif-display mt-2 text-5xl text-[#173c69]">Admin sign-in.</h1><p className="mt-3 max-w-xl text-sm leading-6 text-[#74869a]">Sign in with the account configured for store management. Customer shopping and checkout remain available without an account.</p><Link href="/sign-in" className="btn-primary mt-6 inline-flex items-center gap-2 rounded-xl px-5 py-3 text-sm font-semibold">Continue to sign in <ArrowRight size={16}/></Link><p className="mt-4 text-xs text-[#8a97a5]">Store permissions are verified by the server against the configured admin email allowlist.</p></div></main><Footer/></div>;
  return <AdminPage/>;
}
function Router() {
  return <RoutedErrorBoundary><Switch><Route path="/" component={Home}/><Route path="/product/:productId" component={ProductPage}/><Route path="/checkout" component={Checkout}/><Route path="/admin" component={AdminRoute}/><Route path="/sign-in/*?" component={SignInPage}/><Route path="/sign-up/*?" component={SignUpPage}/><Route component={NotFound}/></Switch></RoutedErrorBoundary>;
}
function ClerkQueryClientCacheInvalidator() {
  const {addListener}=useClerk();const cache=useQueryClient();const previousUserId=useRef<string|null|undefined>(undefined);
  useEffect(()=>{const unsubscribe=addListener(({user})=>{const userId=user?.id??null;if(previousUserId.current!==undefined&&previousUserId.current!==userId)cache.clear();previousUserId.current=userId;});return unsubscribe;},[addListener,cache]);
  return null;
}
function ClerkProviderWithRoutes() {
  const [,setLocation]=useLocation();
  return <ClerkProvider publishableKey={clerkPubKey} proxyUrl={clerkProxyUrl} appearance={clerkAppearance} signInUrl={`${basePath}/sign-in`} signUpUrl={`${basePath}/sign-up`} localization={{signIn:{start:{title:'Welcome back',subtitle:'Sign in to manage Synkline Stores'}},signUp:{start:{title:'Store access',subtitle:'Create an account only if you have been authorized by the store owner'}}}} routerPush={to=>setLocation(stripBase(to))} routerReplace={to=>setLocation(stripBase(to),{replace:true})}><ClerkQueryClientCacheInvalidator/><Router/></ClerkProvider>;
}
function RoutedErrorBoundary({ children }: { children: ReactNode }) { const [location] = useLocation(); return <ErrorBoundary resetKey={location}>{children}</ErrorBoundary>; }
function App() { return <QueryClientProvider client={queryClient}><TooltipProvider><WouterRouter base={basePath}><ClerkProviderWithRoutes/></WouterRouter><Toaster/></TooltipProvider></QueryClientProvider>; }
export default App;
